head.script:
scwin.onpageload = function() {
    for(let i = 0; i < dataList1.getRowCount(); i++){
        if (dataList1.getCellData(i, "chk") === "Y") {
        grd1.setCellReadOnly(i, "chk", false);
        grd1.setCellInputType(i, "chk", {
        inputType: "checkbox",
        });

    }
    else {
        grd1.setCellReadOnly(i, "chk", true);
        grd1.setCellInputType(i, "chk", {
        inputType: "text",
        });
    }
    }
};

	scwin.checkCheckboxStates = function(tbodyId, skipIndex) {
		const tbody = WebSquare.wUnit.getDomById(tbodyId);
		const rows = Array.from(tbody.querySelectorAll('tr')); // NodeList를 배열로 변환
		const checkboxStates = [];
		let reValue = true;
		rows.forEach((row, index) => {
			if (row.classList.contains('w2grid_hidedRow')) {
				return; 
			}
			const checkboxCell = row.querySelector('td[data-colindex="1"]');
			if (checkboxCell) {
				const checkbox = checkboxCell.querySelector('input[type="checkbox"]');
				if(index != skipIndex){
					if (!checkbox.checked) {
						reValue = false;
					}
				}
			}
		});

		return reValue;
	}
	scwin.checkVal1 = function() {
		return scwin.checkCheckboxStates('grd1_body_tbody', 2);
	}
	scwin.checkVal2 = function() {
		return !scwin.checkCheckboxStates('grd1_body_tbody', 2);
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('grd1_cell_2_0').querySelector('input[type="checkbox"]').checked
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_column6').querySelectorAll('input')[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_column6').querySelectorAll('input')[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()","true");
		WebSquare.wUnit.addCommand("pause", "500");	

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_column6').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd1_column6').querySelectorAll('input')[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()","true");
		WebSquare.wUnit.addCommand("pause", "500");			

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
